590	// Cálculo de pontos, conquistas e rankings.
591	// Tudo é calculado a partir dos dados reais: se um post ou curtida
592	// for apagado, a pontuação se ajusta sozinha.
593	const db = require('./db');
594	const { PONTOS, CONQUISTAS } = require('./regras');
595	
596	const SQL_STATS = `
597	SELECT u.id, u.nome, u.curso, u.avatar,
598	  (SELECT COUNT(*) FROM posts p WHERE p.usuario_id = u.id) AS posts,
599	  (SELECT COUNT(DISTINCT c.post_id) FROM comentarios c JOIN posts p ON p.id = c.post_id
600	     WHERE c.usuario_id = u.id AND p.usuario_id <> u.id) AS comentarios,
601	  (SELECT COUNT(*) FROM curtidas l JOIN posts p ON p.id = l.post_id
602	     WHERE p.usuario_id = u.id AND l.usuario_id <> u.id) AS curtidas,
603	  (SELECT COUNT(*) FROM medalhas m WHERE m.aluno_id = u.id) AS medalhas,
604	  (SELECT COALESCE(SUM(t.pontos), 0) FROM medalhas m JOIN tipos_medalha t ON t.id = m.tipo_id
605	     WHERE m.aluno_id = u.id) AS pontos_medalhas
606	FROM usuarios u
607	WHERE u.papel = 'aluno'`;
608	
609	function calcular(s) {
610	  const conquistas = CONQUISTAS.filter((c) => c.atingiu(s));
611	  const pontosConquistas = conquistas.reduce((soma, c) => soma + c.bonus, 0);
612	  const total =
613	    s.posts * PONTOS.post +
614	    s.comentarios * PONTOS.comentario +
615	    s.curtidas * PONTOS.curtida +
616	    s.pontos_medalhas +
617	    pontosConquistas;
618	  return { ...s, conquistas, pontos_conquistas: pontosConquistas, total };
619	}
620	
621	function ranking(curso) {
622	  let lista = db.prepare(SQL_STATS).all().map(calcular);
623	  if (curso) lista = lista.filter((a) => a.curso === curso);
624	  lista.sort((a, b) => b.total - a.total || a.nome.localeCompare(b.nome, 'pt-BR'));
625	  // Empatados ficam na mesma posição.
626	  lista.forEach((a, i) => {
627	    a.posicao = i > 0 && lista[i - 1].total === a.total ? lista[i - 1].posicao : i + 1;
628	  });
629	  return lista;
630	}
631	
632	function statsDoAluno(id) {
633	  const row = db.prepare(SQL_STATS + ' AND u.id = ?').get(id);
634	  if (!row) return null;
635	  const s = calcular(row);
636	  s.posicao_geral = ranking().find((a) => a.id === id)?.posicao;
637	  s.posicao_curso = s.curso ? ranking(s.curso).find((a) => a.id === id)?.posicao : null;
638	  return s;
639	}
