641	// Registra as conquistas que o aluno acabou de desbloquear (para aparecerem no feed).
642	// Conquistas já registradas são ignoradas; se o aluno perder uma depois
643	// (ex.: apagou posts), o registro fica como histórico.
644	function registrarConquistas(alunoId, anunciar = true) {
645	  const row = db.prepare(SQL_STATS + ' AND u.id = ?').get(alunoId);
646	  if (!row) return;
647	  const inserir = db.prepare('INSERT OR IGNORE INTO conquistas_alunos (aluno_id, conquista, anunciar) VALUES (?, ?, ?)');
