384	// Prêmios: medalhas dadas por professores + conquistas desbloqueadas.
385	function premios({ stats, medalhas, proprio, primeiroNome }) {
386	  const ganhas = CONQUISTAS.filter((c) => stats.conquistas.some((x) => x.id === c.id));
387	  const faltam = CONQUISTAS.filter((c) => !ganhas.includes(c));
388	  const total = medalhas.length + ganhas.length;
389	  return html`<section class="cartao">
390	  <h2>Prêmios <span class="contador">${total}</span></h2>
391	  ${total === 0 ? html`<p class="muted">${proprio ? 'Você' : primeiroNome} ainda não ganhou prêmios. Posts, curtidas e medalhas dos professores desbloqueiam os primeiros!</p>` : ''}
392	  ${
393	    medalhas.length
394	      ? html`<h3>Medalhas dos professores</h3>
395	    <ul class="medalhas">
396	      ${medalhas.map(
397	        (m) => html`<li><span class="emoji">${m.emoji}</span><div><strong>${m.nome}</strong> <span class="pts">+${m.pontos}</span>
398	          <small class="muted">por ${m.professor_nome || 'professor(a)'} · ${tempoRelativo(m.criado_em)}</small>
399	          ${m.mensagem ? html`<p>“${m.mensagem}”</p>` : ''}</div></li>`,
400	      )}
401	    </ul>`
402	      : ''
403	  }
404	  ${
405	    ganhas.length
406	      ? html`<h3>Conquistas</h3>
407	    <ul class="conquistas">${ganhas.map((c) => itemConquista(c, true))}</ul>`
408	      : ''
409	  }
410	  ${
411	    faltam.length
412	      ? html`<details class="faltam">
413	    <summary>${proprio ? 'Próximas conquistas' : 'Conquistas que faltam'} (${faltam.length})</summary>
414	    <ul class="conquistas">${faltam.map((c) => itemConquista(c, false))}</ul>
415	  </details>`
416	      : ''
417	  }
418	</section>`;
419	}
