441	function ranking({ lista, curso, usuario, tiposMedalha }) {
442	  const trofeu = (pos) => ({ 1: '🥇', 2: '🥈', 3: '🥉' })[pos] || `${pos}º`;
443	  return html`<section class="cartao">
