13	  --raio: 16px;
14	  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
15	  color-scheme: light;
16	}
17	
18	@media (prefers-color-scheme: dark) {
19	  :root {
20	    --fundo: #0f0d17;
21	    --cartao: #1a1726;
22	    --texto: #f1eff8;
23	    --muted: #a19bb8;
24	    --borda: #2d2840;
25	    --primaria: #a78bfa;
26	    --primaria-2: #f472b6;
27	    --primaria-suave: #2a2142;
