:root {
  --fundo: #f4f2f8;
  --cartao: #ffffff;
  --texto: #1c1830;
  --muted: #6b6680;
  --borda: #e4e0ee;
  --primaria: #5b21b6;
  --primaria-2: #db2777;
  --primaria-suave: #ede9fe;
  --perigo: #dc2626;
  --sucesso: #15803d;
  --ouro: #f59e0b;
  --raio: 16px;
  font-family: system-ui, -apple-system, 'Segoe UI', Roboto, sans-serif;
  color-scheme: light;
}

@media (prefers-color-scheme: dark) {
