    --primaria: #a78bfa;
    --primaria-2: #f472b6;
    --primaria-suave: #2a2142;
    --perigo: #f87171;
    --sucesso: #4ade80;
    color-scheme: dark;
  }
}

* { box-sizing: border-box; }
body { margin: 0; background: var(--fundo); color: var(--texto); line-height: 1.45; }
