1	// Testa os fluxos principais do Maxx num banco temporário.
2	const { test, before, after } = require('node:test');
3	const assert = require('node:assert/strict');
4	const fs = require('node:fs');
5	const os = require('node:os');
6	const path = require('node:path');
7	
8	const pasta = fs.mkdtempSync(path.join(os.tmpdir(), 'maxx-teste-'));
9	process.env.MAXX_DADOS = pasta;
10	process.env.ADMIN_SENHA = 'senha-admin-teste';
11	process.env.CODIGO_BANCA = 'banca-teste';
