30	// Cliente simples que guarda o cookie de sessão.
31	function cliente() {
32	  let cookie = '';
33	  async function req(metodo, caminho, corpo) {
34	    const opcoes = { method: metodo, redirect: 'manual', headers: { cookie } };
35	    if (corpo instanceof FormData) opcoes.body = corpo;
36	    else if (corpo) {
37	      opcoes.body = new URLSearchParams(corpo);
38	      opcoes.headers['content-type'] = 'application/x-www-form-urlencoded';
39	    }
40	    const r = await fetch(base + caminho, opcoes);
41	    const setCookie = r.headers.get('set-cookie');
42	    if (setCookie) cookie = setCookie.split(';')[0];
43	    return { status: r.status, local: r.headers.get('location'), html: await r.text() };
44	  }
45	  return { get: (c) => req('GET', c), post: (c, corpo) => req('POST', c, corpo) };
46	}
