48	async function cadastrar(nome, email, curso) {
49	  const c = cliente();
50	  const r = await c.post('/cadastrar', { nome, email, curso, senha: 'senha12345' });
51	  assert.equal(r.status, 302, `cadastro de ${email} falhou`);
52	  return c;
53	}
54	
55	test('fluxo completo', async () => {
56	  // Sem login, vai para a tela de entrar.
57	  const anon = cliente();
58	  assert.equal((await anon.get('/')).local, '/entrar');
59	  assert.equal((await anon.get('/ranking')).local, '/entrar');
60	
61	  // E-mail de fora da faculdade é recusado.
62	  const fora = await anon.post('/cadastrar', { nome: 'Fulano', email: 'fulano@gmail.com', curso: 'Direito', senha: 'senha12345' });
63	  assert.equal(fora.status, 400);
64	  assert.match(fora.html, /e-mail da faculdade/);
65	
66	  const ana = await cadastrar('Ana Souza', 'ana@unimax.edu.br', 'Direito');
67	  const bruno = await cadastrar('Bruno Lima', 'bruno@unimax.edu.br', 'Psicologia');
68	  const prof = await cadastrar('Prof. Carla', 'carla@unimax.edu.br', 'Direito');
69	
70	  // E-mail repetido é recusado.
71	  const repetido = await anon.post('/cadastrar', { nome: 'Ana', email: 'ANA@unimax.edu.br', curso: 'Direito', senha: 'senha12345' });
72	  assert.match(repetido.html, /Já existe uma conta/);
73	
74	  // Ana publica um post de texto e um com imagem.
75	  assert.equal((await ana.post('/posts', { legenda: 'Primeiro dia de aula! <script>alert(1)</script>' })).status, 302);
76	  const form = new FormData();
77	  form.append('legenda', 'Foto do campus');
78	  form.append('imagem', new Blob([Buffer.from('89504e470d0a1a0a', 'hex')], { type: 'image/png' }), 'foto.png');
79	  assert.equal((await ana.post('/posts', form)).status, 302);
80	
81	  // Arquivo que não é imagem é recusado.
82	  const ruim = new FormData();
83	  ruim.append('imagem', new Blob(['oi'], { type: 'text/html' }), 'x.html');
84	  assert.equal((await ana.post('/posts', ruim)).status, 400);
85	
86	  // O feed mostra o post e o conteúdo está escapado (sem XSS).
87	  const feed = await bruno.get('/');
88	  assert.match(feed.html, /Primeiro dia de aula!/);
89	  assert.ok(!feed.html.includes('<script>alert(1)</script>'));
90	  assert.match(feed.html, /&lt;script&gt;/);
91	
92	  // A conquista do primeiro post aparece no feed (uma vez só, mesmo com 2 posts).
93	  assert.match(feed.html, /Ana desbloqueou <span class="evento-destaque">Primeiro clique/);
94	  assert.equal(feed.html.match(/Primeiro clique/g).length, 1);
95	
96	  // Bruno curte e comenta os posts da Ana.
97	  await bruno.post('/posts/1/curtir', { voltar: '/' });
98	  await bruno.post('/posts/2/curtir', { voltar: 'https://site-malicioso.com' }).then((r) => assert.equal(r.local, '/#post-2'));
99	  await bruno.post('/posts/1/comentar', { texto: 'Bem-vinda!' });
100	  await bruno.post('/posts/1/comentar', { texto: 'Comentário repetido não soma pontos de novo' });
101	  // Comentar direto pelo feed volta para o post no feed, e o comentário aparece lá.
102	  assert.equal((await bruno.post('/posts/2/comentar', { texto: 'Que vista!', voltar: '/' })).local, '/#post-2');
103	  assert.equal((await bruno.post('/posts/2/comentar', { texto: 'x', voltar: '//site-malicioso.com' })).local, '/#post-2');
104	  assert.match((await ana.get('/')).html, /Que vista!/);
105	  // Curtir o próprio post não dá pontos.
106	  await ana.post('/posts/1/curtir', { voltar: '/' });
107	
108	  // Aluno não pode dar medalha nem postar no mural.
109	  assert.equal((await bruno.post('/u/2/medalha', { tipo_id: '1' })).status, 403);
110	  assert.equal((await bruno.post('/mural', { titulo: 'x', texto: 'y' })).status, 403);
111	  assert.equal((await bruno.get('/admin')).status, 403);
112	
113	  // A faculdade entra, promove a Carla a professora e publica um aviso fixado.
114	  const admin = cliente();
115	  assert.equal((await admin.post('/entrar', { email: 'admin@unimax.edu.br', senha: 'senha-admin-teste' })).status, 302);
116	  assert.equal((await admin.post('/admin/usuarios/4/papel', { papel: 'professor' })).status, 302);
117	  await admin.post('/mural', { titulo: 'Semana de provas', texto: 'Provas de 10 a 14/11.', fixado: '1' });
118	  const feedAna = (await ana.get('/')).html;
119	  assert.match(feedAna, /Semana de provas/);
120	  // O menu avisa que tem 1 aviso novo; ao abrir o mural ele aparece como "Novo" e depois some.
121	  assert.match(feedAna, /class="bolinha" aria-hidden="true">1</);
122	  const muralAna = (await ana.get('/mural')).html;
123	  assert.match(muralAna, /Provas de 10 a 14\/11/);
124	  assert.match(muralAna, /selo-novo/);
125	  assert.ok(!muralAna.includes('class="bolinha"'));
126	  assert.ok(!(await ana.get('/')).html.includes('class="bolinha"'));
127	  assert.ok(!(await ana.get('/mural')).html.includes('selo-novo'));
128	
129	  // A professora também publica no mural (sem poder fixar), com o nome dela no aviso.
130	  assert.equal((await prof.post('/mural', { titulo: 'Aula de quinta cancelada', texto: 'Reposição na sexta.', fixado: '1' })).local, '/mural#aviso-2');
131	  const muralBruno = (await bruno.get('/mural')).html;
132	  assert.match(muralBruno, /Prof. Carla[\s\S]*Aula de quinta cancelada/);
133	  assert.equal(muralBruno.match(/📌 Fixado/g).length, 1);
134	  assert.match((await ana.get('/')).html, /class="bolinha" aria-hidden="true">1</);
135	  // Aluno não apaga aviso; a professora só apaga os dela; a faculdade apaga qualquer um.
136	  assert.equal((await bruno.post('/mural/2/apagar')).status, 403);
137	  assert.equal((await prof.post('/mural/1/apagar')).status, 403);
138	  assert.equal((await prof.post('/mural/1/fixar')).status, 403);
139	  assert.equal((await prof.post('/mural/2/apagar')).status, 302);
140	  assert.ok(!(await ana.get('/mural')).html.includes('Aula de quinta cancelada'));
141	
142	  // Professora dá medalha para a Ana (id 2) e não pode dar para outra professora.
143	  assert.equal((await prof.post('/u/2/medalha', { tipo_id: '1', mensagem: 'Excelente seminário' })).local, '/u/2?ok=medalha');
144	  assert.equal((await prof.post('/u/4/medalha', { tipo_id: '1' })).status, 400);
145	
146	  // A medalha e a conquista Medalhista aparecem no feed de todo mundo.
147	  const feedBruno = (await bruno.get('/')).html;
148	  assert.match(feedBruno, /Ana ganhou <span class="evento-destaque">Excelência acadêmica/);
149	  assert.match(feedBruno, /Excelente seminário/);
150	  assert.match(feedBruno, /Ana desbloqueou <span class="evento-destaque">Medalhista/);
151	
152	  // Pontos da Ana: 2 posts (20) + 2 curtidas de outros (4) + medalha Excelência (50)
153	  //              + conquistas Primeiro clique (20) e Medalhista (20) = 114
154	  // Pontos do Bruno: 2 posts comentados (6).
155	  const ranking = await ana.get('/ranking');
156	  assert.match(ranking.html, /Ana Souza[\s\S]*114[\s\S]*Bruno Lima[\s\S]*6 <small>pts/);
157	  const perfil = await ana.get('/u/2');
158	  assert.match(perfil.html, /114<\/strong><span>pontos/);
159	  assert.match(perfil.html, /Excelente seminário/);
160	  // Perfil: 1 medalha + 2 conquistas = 3 prêmios, extrato dos pontos e os 2 posts.
161	  assert.match(perfil.html, /3<\/strong><span>prêmios/);
162	  assert.match(perfil.html, /2 posts publicados<\/td><td class="pts">\+20/);
163	  assert.match(perfil.html, /1 medalha de professor<\/td><td class="pts">\+50/);
164	  assert.match(perfil.html, /Posts <span class="contador">2/);
165	  assert.match(perfil.html, /Próximas conquistas/);
166	  assert.match((await bruno.get('/u/2')).html, /Conquistas que faltam/);
167	
168	  // Ranking por curso: Psicologia só tem o Bruno; professores não aparecem.
169	  const psico = await ana.get('/ranking?curso=Psicologia');
170	  assert.match(psico.html, /Bruno Lima/);
171	  assert.ok(!psico.html.includes('Ana Souza'));
172	  assert.ok(!ranking.html.includes('Prof. Carla</strong>'));
173	
174	  // Bruno não pode apagar post da Ana; a Ana pode.
175	  assert.equal((await bruno.post('/posts/1/apagar')).status, 403);
176	  assert.equal((await ana.post('/posts/1/apagar')).status, 302);
177	  assert.equal((await ana.get('/posts/1')).status, 404);
178	
179	  // Sair encerra a sessão.
180	  await ana.post('/sair');
181	  assert.equal((await ana.get('/')).local, '/entrar');
182	});
183	
184	test('acesso da banca', async () => {
185	  const config = require('../src/config');
186	  const anon = cliente();
187	
188	  // A tela de entrar mostra a caixa da banca.
189	  assert.match((await anon.get('/entrar')).html, /Banca do TCC/);
190	
191	  // Código errado não entra.
192	  const errado = await anon.post('/banca', { codigo: 'chute', perfil: 'aluno' });
193	  assert.equal(errado.status, 401);
194	  assert.match(errado.html, /Código de acesso incorreto/);
195	
196	  // Com o código certo, entra como aluno, professor ou faculdade (sem ligar para maiúsculas).
197	  const aluno = cliente();
198	  assert.equal((await aluno.post('/banca', { codigo: 'Banca-Teste', perfil: 'aluno' })).local, '/');
199	  assert.equal((await aluno.post('/posts', { legenda: 'Post da banca' })).status, 302);
200	  const prof = cliente();
201	  await prof.post('/banca', { codigo: 'banca-teste', perfil: 'professor' });
202	  const idAluno = require('../src/db').prepare("SELECT id FROM usuarios WHERE email = 'banca.aluno@unimax.edu.br'").get().id;
203	  assert.equal((await prof.post(`/u/${idAluno}/medalha`, { tipo_id: '1' })).status, 302);
204	  const fac = cliente();
205	  await fac.post('/banca', { codigo: 'banca-teste', perfil: 'admin' });
206	  assert.equal((await fac.get('/admin')).status, 200);
207	
208	  // Ninguém consegue se cadastrar com o e-mail de uma conta da banca, nem entrar com senha.
209	  const cad = await anon.post('/cadastrar', { nome: 'Xavier', email: 'banca.aluno@unimax.edu.br', curso: 'Direito', senha: 'senha12345' });
210	  assert.match(cad.html, /Já existe uma conta/);
211	  assert.equal((await anon.post('/entrar', { email: 'banca.aluno@unimax.edu.br', senha: '!' })).status, 401);
212	
213	  // Desligando o acesso da banca, a caixa some e as sessões da banca param de valer.
214	  config.CODIGO_BANCA = '';
215	  assert.ok(!(await anon.get('/entrar')).html.includes('Banca do TCC'));
216	  assert.equal((await aluno.get('/')).local, '/entrar');
217	  assert.equal((await anon.post('/banca', { codigo: 'banca-teste', perfil: 'aluno' })).local, '/entrar');
218	});
